import type { Request, Response, NextFunction } from 'express';
import { AppError, ValidationError } from '../errors/AppError';

/**
 * Express error-handling middleware ΓÇö must be the last middleware registered.
 *
 * Maps domain errors to Conduit-spec HTTP responses:
 *   - `ValidationError` ΓåÆ 422 with field-level error scoping
 *   - `AppError` subclasses ΓåÆ mapped status with resource-scoped envelope
 *   - Unknown errors ΓåÆ 500 (logged to stderr; detail not exposed to clients)
 *
 * Conduit error envelope format: `{ errors: { [resource]: ["message", ...] } }`
 *
 * @param err - The thrown error
 * @param _req - Incoming request (unused)
 * @param res - Response object
 * @param _next - Required 4-argument signature so Express recognises this as an error handler
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function errorHandler(err: Error, _req: Request, res: Response, _next: NextFunction): void {
  if (err instanceof ValidationError) {
    res.status(422).json({ errors: err.fields });
    return;
  }
  if (err instanceof AppError) {
    res.status(err.statusCode).json({ errors: { [err.resource]: [err.message] } });
    return;
  }
  console.error('[Unhandled error]', err);
  res.status(500).json({ errors: { server: ['Internal server error'] } });
}

import type {
  Article,
  ArticleFilters,
  CreateArticleData,
  PaginatedArticles,
  Pagination,
  UpdateArticleData,
} from '../types/domain';
import type { IArticleRepository } from './IArticleRepository';
import type { IUserRepository } from './IUserRepository';
import { NotFoundError } from '../errors/AppError';

/**
 * In-memory implementation of `IArticleRepository` for unit tests.
 *
 * Two modes:
 *   1. Standalone (no userRepo): `create()` stubs the author as `'stub-author'`.
 *      Sufficient for service-level unit tests that verify article logic, not author names.
 *   2. Shared (userRepo injected): `create()` looks up the real author by `authorId`.
 *      Required for route-level integration tests that assert `article.author.username`.
 *
 * Stores articles in a Map keyed by slug. Favorites tracked in a separate Map.
 * Does not implement follow-based filtering in `findFeed` ΓÇö returns all articles.
 *
 * Use `seed()` to pre-populate and `clear()` between test cases.
 */
export class InMemoryArticleRepository implements IArticleRepository {
  private readonly articles: Map<string, Article> = new Map();
  private readonly favoritesBySlug: Map<string, Set<number>> = new Map();
  private nextId = 1;

  constructor(private readonly userRepo?: IUserRepository) {}

  /**
   * Pre-populate the repository with existing articles.
   * Clears current state before seeding.
   *
   * @param articles - Articles to seed (must have unique slugs)
   */
  seed(articles: Article[]): void {
    this.articles.clear();
    this.favoritesBySlug.clear();
    this.nextId = 1;
    for (const article of articles) {
      this.articles.set(article.slug, { ...article });
      if (article.id >= this.nextId) this.nextId = article.id + 1;
    }
  }

  /** Remove all articles and favorites. */
  clear(): void {
    this.articles.clear();
    this.favoritesBySlug.clear();
    this.nextId = 1;
  }

  /** @inheritdoc */
  async findBySlug(slug: string, currentUserId?: number): Promise<Article | null> {
    const article = this.articles.get(slug);
    if (!article) return null;
    return this.withViewerContext(article, currentUserId);
  }

  /** @inheritdoc */
  async findAll(
    filters: ArticleFilters,
    pagination: Pagination,
    currentUserId?: number,
  ): Promise<PaginatedArticles> {
    let articles = Array.from(this.articles.values());

    if (filters.tag) {
      const tag = filters.tag;
      articles = articles.filter((a) => a.tagList.includes(tag));
    }
    if (filters.author) {
      const author = filters.author;
      articles = articles.filter((a) => a.author.username === author);
    }
    if (filters.favorited) {
      const favoritedBy = filters.favorited;
      // In-memory: we can only check by userId since we don't store usernameΓåÆid mapping.
      // Tests that need favorited filtering should use integration tests with Prisma.
      // Fall through without filtering to avoid silent test failures.
      void favoritedBy;
    }

    articles.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
    const articlesCount = articles.length;
    const paginated = articles.slice(pagination.offset, pagination.offset + pagination.limit);

    return {
      articles: paginated.map((a) => this.withViewerContext(a, currentUserId)),
      articlesCount,
    };
  }

  /** @inheritdoc */
  async findFeed(userId: number, pagination: Pagination): Promise<PaginatedArticles> {
    // In-memory: no follow tracking. Returns all articles ordered by date.
    // Unit tests that need accurate feed results should use integration tests.
    const articles = Array.from(this.articles.values()).sort(
      (a, b) => b.createdAt.getTime() - a.createdAt.getTime(),
    );
    const articlesCount = articles.length;
    const paginated = articles.slice(pagination.offset, pagination.offset + pagination.limit);

    return {
      articles: paginated.map((a) => this.withViewerContext(a, userId)),
      articlesCount,
    };
  }

  /** @inheritdoc */
  async create(authorId: number, data: CreateArticleData): Promise<Article> {
    const id = this.nextId++;
    const slug = `${data.title.toLowerCase().replace(/[\s]+/g, '-')}-${id}`;

    // Look up real author info when a user repository is available (route test mode).
    const user = this.userRepo ? await this.userRepo.findById(authorId) : null;
    const author = user
      ? { username: user.username, bio: user.bio, image: user.image, following: false }
      : { username: 'stub-author', bio: null, image: null, following: false };

    const article: Article = {
      id,
      slug,
      title: data.title,
      description: data.description,
      body: data.body,
      authorId,
      author,
      tagList: data.tagList,
      favoritesCount: 0,
      favorited: false,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.articles.set(slug, article);
    return { ...article };
  }

  /** @inheritdoc */
  async update(slug: string, data: UpdateArticleData): Promise<Article> {
    const existing = this.articles.get(slug);
    if (!existing) throw new NotFoundError('article');

    const newTitle = data.title ?? existing.title;
    const newSlug =
      data.title !== undefined
        ? `${newTitle.toLowerCase().replace(/[\s]+/g, '-')}-${existing.id}`
        : slug;

    const updated: Article = {
      ...existing,
      slug: newSlug,
      title: newTitle,
      description: data.description ?? existing.description,
      body: data.body ?? existing.body,
      tagList: data.tagList ?? existing.tagList,
      updatedAt: new Date(),
    };

    if (newSlug !== slug) {
      this.articles.delete(slug);
      const favs = this.favoritesBySlug.get(slug);
      if (favs) {
        this.favoritesBySlug.set(newSlug, favs);
        this.favoritesBySlug.delete(slug);
      }
    }
    this.articles.set(newSlug, updated);
    return { ...updated };
  }

  /** @inheritdoc */
  async delete(slug: string): Promise<void> {
    if (!this.articles.has(slug)) throw new NotFoundError('article');
    this.articles.delete(slug);
    this.favoritesBySlug.delete(slug);
  }

  /** @inheritdoc */
  async addFavorite(userId: number, slug: string): Promise<Article> {
    const article = this.articles.get(slug);
    if (!article) throw new NotFoundError('article');

    let favs = this.favoritesBySlug.get(slug);
    if (!favs) {
      favs = new Set();
      this.favoritesBySlug.set(slug, favs);
    }
    favs.add(userId);

    return this.withViewerContext(article, userId);
  }

  /** @inheritdoc */
  async removeFavorite(userId: number, slug: string): Promise<Article> {
    const article = this.articles.get(slug);
    if (!article) throw new NotFoundError('article');

    const favs = this.favoritesBySlug.get(slug);
    if (favs) favs.delete(userId);

    return this.withViewerContext(article, userId);
  }

  /**
   * Enrich an article with viewer-relative `favorited` and `favoritesCount` fields.
   */
  private withViewerContext(article: Article, currentUserId?: number): Article {
    const favs = this.favoritesBySlug.get(article.slug) ?? new Set<number>();
    return {
      ...article,
      favoritesCount: favs.size,
      favorited: currentUserId !== undefined ? favs.has(currentUserId) : false,
    };
  }
}

import type { User, CreateUserData, UpdateUserData } from '../types/domain';
import type { IUserRepository } from './IUserRepository';
import { ConflictError, NotFoundError } from '../errors/AppError';

/**
 * In-memory implementation of `IUserRepository` for use in unit tests.
 *
 * Satisfies the full port contract without requiring a database connection.
 * Use in tests by injecting into `UserService` constructor ΓÇö no mocking needed.
 *
 * @example
 * const repo = new InMemoryUserRepository();
 * const service = new UserService(repo);
 * beforeEach(() => repo.clear());
 */
export class InMemoryUserRepository implements IUserRepository {
  private readonly store = new Map<number, User>();
  private nextId = 1;

  /**
   * Seed initial user records for test setup.
   *
   * @param users - User entities to pre-populate the store with
   */
  seed(users: User[]): void {
    for (const user of users) {
      this.store.set(user.id, user);
      if (user.id >= this.nextId) this.nextId = user.id + 1;
    }
  }

  /**
   * Remove all stored users and reset the id counter.
   * Call in `beforeEach` to isolate tests.
   */
  clear(): void {
    this.store.clear();
    this.nextId = 1;
  }

  /** @inheritdoc */
  async findById(id: number): Promise<User | null> {
    return this.store.get(id) ?? null;
  }

  /** @inheritdoc */
  async findByEmail(email: string): Promise<User | null> {
    const lower = email.toLowerCase();
    for (const user of this.store.values()) {
      if (user.email === lower) return user;
    }
    return null;
  }

  /** @inheritdoc */
  async findByUsername(username: string): Promise<User | null> {
    for (const user of this.store.values()) {
      if (user.username === username) return user;
    }
    return null;
  }

  /** @inheritdoc */
  async create(data: CreateUserData): Promise<User> {
    for (const user of this.store.values()) {
      if (user.email === data.email.toLowerCase()) {
        throw new ConflictError('email', 'has already been taken');
      }
      if (user.username === data.username) {
        throw new ConflictError('username', 'has already been taken');
      }
    }
    const now = new Date();
    const user: User = {
      id: this.nextId++,
      email: data.email.toLowerCase(),
      username: data.username,
      passwordHash: data.passwordHash,
      bio: null,
      image: null,
      createdAt: now,
      updatedAt: now,
    };
    this.store.set(user.id, user);
    return user;
  }

  /** @inheritdoc */
  async update(id: number, data: UpdateUserData): Promise<User> {
    const existing = this.store.get(id);
    if (!existing) throw new NotFoundError('user');
    for (const user of this.store.values()) {
      if (user.id === id) continue;
      if (data.email !== undefined && user.email === data.email.toLowerCase()) {
        throw new ConflictError('email', 'has already been taken');
      }
      if (data.username !== undefined && user.username === data.username) {
        throw new ConflictError('username', 'has already been taken');
      }
    }
    const updated: User = {
      ...existing,
      ...(data.email !== undefined && { email: data.email.toLowerCase() }),
      ...(data.username !== undefined && { username: data.username }),
      ...(data.passwordHash !== undefined && { passwordHash: data.passwordHash }),
      ...(data.bio !== undefined && { bio: data.bio }),
      ...(data.image !== undefined && { image: data.image }),
      updatedAt: new Date(),
    };
    this.store.set(id, updated);
    return updated;
  }
}

import { PrismaClient, Prisma } from '@prisma/client';
import type {
  Article,
  ArticleFilters,
  CreateArticleData,
  PaginatedArticles,
  Pagination,
  UpdateArticleData,
} from '../types/domain';
import type { IArticleRepository } from './IArticleRepository';
import { NotFoundError } from '../errors/AppError';
import { generateSlug } from '../utils/slugify';

/** Prisma error code for record-not-found on update/delete. */
const PRISMA_NOT_FOUND = 'P2025';

/**
 * Sentinel viewer ID used when no authenticated user is present.
 * User IDs start at 1, so -1 never matches any real user ΓÇö
 * all viewer-relative queries (favorites, following) return empty results.
 */
const NO_VIEWER = -1;

/**
 * Shape of the Prisma article payload returned by all read queries.
 * Manually typed to avoid complex Prisma generic inference throughout the class.
 */
interface ArticleRow {
  id: number;
  slug: string;
  title: string;
  description: string;
  body: string;
  authorId: number;
  createdAt: Date;
  updatedAt: Date;
  author: {
    id: number;
    username: string;
    bio: string | null;
    image: string | null;
    followers: { followerId: number }[];
  };
  tags: { tag: { name: string } }[];
  favorites: { userId: number }[];
  _count: { favorites: number };
}

/**
 * Build the Prisma include object for article queries.
 * All viewer-relative fields (favorited, author.following) are filtered by
 * the sentinel value NO_VIEWER when no authenticated user is present.
 *
 * @param viewerId - Authenticated user ID, or NO_VIEWER (-1) for anonymous
 */
function buildArticleInclude(viewerId: number) {
  return {
    author: {
      select: {
        id: true,
        username: true,
        bio: true,
        image: true,
        followers: {
          where: { followerId: viewerId },
          select: { followerId: true },
        },
      },
    },
    tags: {
      include: { tag: { select: { name: true } } },
      orderBy: { tag: { name: 'asc' as const } },
    },
    favorites: {
      where: { userId: viewerId },
      select: { userId: true },
    },
    _count: { select: { favorites: true } },
  };
}

/**
 * Map a raw Prisma article row to the domain `Article` entity.
 */
function mapToArticle(row: ArticleRow): Article {
  return {
    id: row.id,
    slug: row.slug,
    title: row.title,
    description: row.description,
    body: row.body,
    authorId: row.authorId,
    author: {
      username: row.author.username,
      bio: row.author.bio,
      image: row.author.image,
      following: row.author.followers.length > 0,
    },
    tagList: row.tags.map((t) => t.tag.name),
    favoritesCount: row._count.favorites,
    favorited: row.favorites.length > 0,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

/**
 * Build Prisma where input from optional article list filters.
 */
function buildWhereFromFilters(filters: ArticleFilters): Prisma.ArticleWhereInput {
  const where: Prisma.ArticleWhereInput = {};
  if (filters.tag) {
    where.tags = { some: { tag: { name: filters.tag } } };
  }
  if (filters.author) {
    where.author = { username: filters.author };
  }
  if (filters.favorited) {
    where.favorites = { some: { user: { username: filters.favorited } } };
  }
  return where;
}

/**
 * PostgreSQL-backed implementation of `IArticleRepository` via Prisma.
 *
 * All database I/O for article operations is confined to this adapter.
 * Domain services import `IArticleRepository` only ΓÇö never this class directly.
 * Wire at the composition root (`src/server.ts`).
 */
export class PrismaArticleRepository implements IArticleRepository {
  constructor(private readonly prisma: PrismaClient) {}

  /** @inheritdoc */
  async findBySlug(slug: string, currentUserId?: number): Promise<Article | null> {
    const viewerId = currentUserId ?? NO_VIEWER;
    const row = await this.prisma.article.findUnique({
      where: { slug },
      include: buildArticleInclude(viewerId),
    });
    return row ? mapToArticle(row as unknown as ArticleRow) : null;
  }

  /** @inheritdoc */
  async findAll(
    filters: ArticleFilters,
    pagination: Pagination,
    currentUserId?: number,
  ): Promise<PaginatedArticles> {
    const viewerId = currentUserId ?? NO_VIEWER;
    const where = buildWhereFromFilters(filters);

    const [rows, total] = await this.prisma.$transaction([
      this.prisma.article.findMany({
        where,
        take: pagination.limit,
        skip: pagination.offset,
        orderBy: { createdAt: 'desc' },
        include: buildArticleInclude(viewerId),
      }),
      this.prisma.article.count({ where }),
    ]);

    return {
      articles: rows.map((r) => mapToArticle(r as unknown as ArticleRow)),
      articlesCount: total,
    };
  }

  /** @inheritdoc */
  async findFeed(userId: number, pagination: Pagination): Promise<PaginatedArticles> {
    const where: Prisma.ArticleWhereInput = {
      author: { followers: { some: { followerId: userId } } },
    };

    const [rows, total] = await this.prisma.$transaction([
      this.prisma.article.findMany({
        where,
        take: pagination.limit,
        skip: pagination.offset,
        orderBy: { createdAt: 'desc' },
        include: buildArticleInclude(userId),
      }),
      this.prisma.article.count({ where }),
    ]);

    return {
      articles: rows.map((r) => mapToArticle(r as unknown as ArticleRow)),
      articlesCount: total,
    };
  }

  /** @inheritdoc */
  async create(authorId: number, data: CreateArticleData): Promise<Article> {
    const slug = generateSlug(data.title);
    const row = await this.prisma.article.create({
      data: {
        slug,
        title: data.title,
        description: data.description,
        body: data.body,
        authorId,
        tags: {
          create: data.tagList.map((name) => ({
            tag: { connectOrCreate: { where: { name }, create: { name } } },
          })),
        },
      },
      include: buildArticleInclude(NO_VIEWER),
    });
    return mapToArticle(row as unknown as ArticleRow);
  }

  /** @inheritdoc */
  async update(slug: string, data: UpdateArticleData): Promise<Article> {
    const newSlug = data.title !== undefined ? generateSlug(data.title) : undefined;
    try {
      const row = await this.prisma.article.update({
        where: { slug },
        data: {
          ...(data.title !== undefined && { title: data.title, slug: newSlug }),
          ...(data.description !== undefined && { description: data.description }),
          ...(data.body !== undefined && { body: data.body }),
          ...(data.tagList !== undefined && {
            tags: {
              deleteMany: {},
              create: data.tagList.map((name) => ({
                tag: { connectOrCreate: { where: { name }, create: { name } } },
              })),
            },
          }),
        },
        include: buildArticleInclude(NO_VIEWER),
      });
      return mapToArticle(row as unknown as ArticleRow);
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === PRISMA_NOT_FOUND) {
        throw new NotFoundError('article');
      }
      throw err;
    }
  }

  /** @inheritdoc */
  async delete(slug: string): Promise<void> {
    try {
      await this.prisma.article.delete({ where: { slug } });
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === PRISMA_NOT_FOUND) {
        throw new NotFoundError('article');
      }
      throw err;
    }
  }

  /** @inheritdoc */
  async addFavorite(userId: number, slug: string): Promise<Article> {
    const article = await this.prisma.article.findUnique({
      where: { slug },
      select: { id: true },
    });
    if (!article) throw new NotFoundError('article');

    await this.prisma.articleFavorite.upsert({
      where: { userId_articleId: { userId, articleId: article.id } },
      create: { userId, articleId: article.id },
      update: {},
    });

    const row = await this.prisma.article.findUnique({
      where: { slug },
      include: buildArticleInclude(userId),
    });
    return mapToArticle(row as unknown as ArticleRow);
  }

  /** @inheritdoc */
  async removeFavorite(userId: number, slug: string): Promise<Article> {
    const article = await this.prisma.article.findUnique({
      where: { slug },
      select: { id: true },
    });
    if (!article) throw new NotFoundError('article');

    try {
      await this.prisma.articleFavorite.delete({
        where: { userId_articleId: { userId, articleId: article.id } },
      });
    } catch (err) {
      // Idempotent: ignore P2025 ΓÇö favorite already absent, treat as success
      if (
        !(
          err instanceof Prisma.PrismaClientKnownRequestError && err.code === PRISMA_NOT_FOUND
        )
      ) {
        throw err;
      }
    }

    const row = await this.prisma.article.findUnique({
      where: { slug },
      include: buildArticleInclude(userId),
    });
    return mapToArticle(row as unknown as ArticleRow);
  }
}

import { PrismaClient, Prisma } from '@prisma/client';
import type { Comment } from '../types/domain';
import type { ICommentRepository } from './ICommentRepository';
import { NotFoundError } from '../errors/AppError';

/** Prisma error code for record-not-found on update/delete. */
const PRISMA_NOT_FOUND = 'P2025';

/**
 * Sentinel viewer ID used when no authenticated user is present.
 * Matches the convention in PrismaArticleRepository ΓÇö never equals a real user ID.
 */
const NO_VIEWER = -1;

/**
 * Shape of the Prisma comment payload returned by all read queries.
 * Manually typed to avoid complex Prisma generic inference throughout the class.
 */
interface CommentRow {
  id: number;
  body: string;
  authorId: number;
  articleId: number;
  createdAt: Date;
  updatedAt: Date;
  author: {
    id: number;
    username: string;
    bio: string | null;
    image: string | null;
    followers: { followerId: number }[];
  };
}

/**
 * Build the Prisma include object for comment queries.
 * Author's `following` field is viewer-relative, filtered by sentinel value NO_VIEWER
 * when no authenticated user is present.
 *
 * @param viewerId - Authenticated user ID, or NO_VIEWER (-1) for anonymous
 */
function buildCommentInclude(viewerId: number) {
  return {
    author: {
      select: {
        id: true,
        username: true,
        bio: true,
        image: true,
        followers: {
          where: { followerId: viewerId },
          select: { followerId: true },
        },
      },
    },
  };
}

/**
 * Map a raw Prisma comment row to the domain `Comment` entity.
 */
function mapToComment(row: CommentRow): Comment {
  return {
    id: row.id,
    body: row.body,
    authorId: row.authorId,
    articleId: row.articleId,
    author: {
      username: row.author.username,
      bio: row.author.bio,
      image: row.author.image,
      following: row.author.followers.length > 0,
    },
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

/**
 * PostgreSQL-backed implementation of `ICommentRepository` via Prisma.
 *
 * All database I/O for comment operations is confined to this adapter.
 * Domain services import `ICommentRepository` only ΓÇö never this class directly.
 * Wire at the composition root (`src/server.ts`).
 */
export class PrismaCommentRepository implements ICommentRepository {
  constructor(private readonly prisma: PrismaClient) {}

  /** @inheritdoc */
  async findById(id: number): Promise<Comment | null> {
    const row = await this.prisma.comment.findUnique({
      where: { id },
      include: buildCommentInclude(NO_VIEWER),
    });
    return row ? mapToComment(row as unknown as CommentRow) : null;
  }

  /** @inheritdoc */
  async findByArticleSlug(articleSlug: string, currentUserId?: number): Promise<Comment[]> {
    const viewerId = currentUserId ?? NO_VIEWER;
    const rows = await this.prisma.comment.findMany({
      where: { article: { slug: articleSlug } },
      orderBy: { createdAt: 'desc' },
      include: buildCommentInclude(viewerId),
    });
    return rows.map((r) => mapToComment(r as unknown as CommentRow));
  }

  /** @inheritdoc */
  async create(authorId: number, articleSlug: string, body: string): Promise<Comment> {
    const article = await this.prisma.article.findUnique({
      where: { slug: articleSlug },
      select: { id: true },
    });
    if (!article) throw new NotFoundError('article');

    const row = await this.prisma.comment.create({
      data: { body, authorId, articleId: article.id },
      include: buildCommentInclude(authorId),
    });
    return mapToComment(row as unknown as CommentRow);
  }

  /** @inheritdoc */
  async delete(id: number): Promise<void> {
    try {
      await this.prisma.comment.delete({ where: { id } });
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === PRISMA_NOT_FOUND) {
        throw new NotFoundError('comment');
      }
      throw err;
    }
  }
}

import { PrismaClient, Prisma } from '@prisma/client';
import type { User, CreateUserData, UpdateUserData } from '../types/domain';
import type { IUserRepository } from './IUserRepository';
import { ConflictError, NotFoundError } from '../errors/AppError';

/** Prisma error code for unique constraint violations. */
const PRISMA_UNIQUE_VIOLATION = 'P2002';
/** Prisma error code for record-not-found on update/delete. */
const PRISMA_NOT_FOUND = 'P2025';

/**
 * PostgreSQL-backed implementation of `IUserRepository` via Prisma.
 *
 * All database I/O is confined to this adapter. Domain services import
 * the `IUserRepository` interface only ΓÇö never this class directly.
 * Wire at the composition root (`src/server.ts`).
 */
export class PrismaUserRepository implements IUserRepository {
  constructor(private readonly prisma: PrismaClient) {}

  /**
   * Find a user by their internal numeric ID.
   *
   * @param id - The user's primary key
   * @returns The user entity or null if not found
   */
  async findById(id: number): Promise<User | null> {
    return this.prisma.user.findUnique({ where: { id } });
  }

  /**
   * Find a user by their email address (case-insensitive via lowercase storage).
   *
   * @param email - Email to search for
   * @returns The user entity or null if not found
   */
  async findByEmail(email: string): Promise<User | null> {
    return this.prisma.user.findUnique({ where: { email: email.toLowerCase() } });
  }

  /**
   * Find a user by their unique username (case-sensitive).
   *
   * @param username - Username to search for
   * @returns The user entity or null if not found
   */
  async findByUsername(username: string): Promise<User | null> {
    return this.prisma.user.findUnique({ where: { username } });
  }

  /**
   * Create a new user record.
   *
   * @param data - User creation payload; `passwordHash` must be a pre-hashed argon2 string
   * @returns The created user with all fields including id and timestamps
   * @throws `ConflictError` if email or username is already taken
   */
  async create(data: CreateUserData): Promise<User> {
    try {
      return await this.prisma.user.create({
        data: {
          email: data.email.toLowerCase(),
          username: data.username,
          passwordHash: data.passwordHash,
        },
      });
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === PRISMA_UNIQUE_VIOLATION) {
        const target = (err.meta?.target as string[] | undefined) ?? [];
        if (target.includes('email')) throw new ConflictError('email', 'has already been taken');
        if (target.includes('username')) throw new ConflictError('username', 'has already been taken');
      }
      throw err;
    }
  }

  /**
   * Update an existing user with partial data.
   *
   * @param id - The user's primary key
   * @param data - Partial update payload; only provided fields are changed
   * @returns The updated user entity
   * @throws `NotFoundError` if no user with the given id exists
   * @throws `ConflictError` if the new email or username is already taken
   */
  async update(id: number, data: UpdateUserData): Promise<User> {
    try {
      const patch: Prisma.UserUpdateInput = {};
      if (data.email !== undefined) patch.email = data.email.toLowerCase();
      if (data.username !== undefined) patch.username = data.username;
      if (data.passwordHash !== undefined) patch.passwordHash = data.passwordHash;
      if (data.bio !== undefined) patch.bio = data.bio;
      if (data.image !== undefined) patch.image = data.image;
      return await this.prisma.user.update({ where: { id }, data: patch });
    } catch (err) {
      if (err instanceof Prisma.PrismaClientKnownRequestError) {
        if (err.code === PRISMA_NOT_FOUND) throw new NotFoundError('user');
        if (err.code === PRISMA_UNIQUE_VIOLATION) {
          const target = (err.meta?.target as string[] | undefined) ?? [];
          if (target.includes('email')) throw new ConflictError('email', 'has already been taken');
          if (target.includes('username')) throw new ConflictError('username', 'has already been taken');
        }
      }
      throw err;
    }
  }
}

import request from 'supertest';
import { createApp } from '../app';
import { InMemoryUserRepository } from '../repositories/InMemoryUserRepository';
import { InMemoryProfileRepository } from '../repositories/InMemoryProfileRepository';
import { InMemoryArticleRepository } from '../repositories/InMemoryArticleRepository';
import { InMemoryCommentRepository } from '../repositories/InMemoryCommentRepository';
import { InMemoryTagRepository } from '../repositories/InMemoryTagRepository';
import { UserService } from '../services/UserService';
import { ProfileService } from '../services/ProfileService';
import { ArticleService } from '../services/ArticleService';
import { CommentService } from '../services/CommentService';
import { TagService } from '../services/TagService';

// Shared user store ΓÇö all repos that need user lookups reference this instance.
const userRepo = new InMemoryUserRepository();
const profileRepo = new InMemoryProfileRepository(userRepo);
const articleRepo = new InMemoryArticleRepository(userRepo);
const commentRepo = new InMemoryCommentRepository(userRepo);
const tagRepo = new InMemoryTagRepository(articleRepo);

const userService = new UserService(userRepo);
const profileService = new ProfileService(profileRepo);
const articleService = new ArticleService(articleRepo);
const commentService = new CommentService(commentRepo, articleRepo);
const tagService = new TagService(tagRepo);
const app = createApp({ userService, profileService, articleService, commentService, tagService });

const ALICE = { email: 'alice@example.com', username: 'alice', password: 'Password123!' };
const BOB = { email: 'bob@example.com', username: 'bob', password: 'Password123!' };

const ARTICLE_PAYLOAD = {
  title: 'How to Train Your Dragon',
  description: 'Ever wonder how?',
  body: 'You have to believe',
  tagList: ['dragons', 'training'],
};

/** Register a user and return their JWT token. */
async function registerAndGetToken(user: typeof ALICE): Promise<string> {
  const res = await request(app).post('/api/users').send({ user });
  return res.body.user.token as string;
}

/** Create an article and return its slug. */
async function createArticle(
  token: string,
  payload: typeof ARTICLE_PAYLOAD = ARTICLE_PAYLOAD,
): Promise<string> {
  const res = await request(app)
    .post('/api/articles')
    .set('Authorization', `Token ${token}`)
    .send({ article: payload });
  return res.body.article.slug as string;
}

beforeEach(() => {
  userRepo.clear();
  profileRepo.clear();
  articleRepo.clear();
  commentRepo.clear();
});

// =============================================================================
// GET /api/articles
// =============================================================================
describe('GET /api/articles', () => {
  it('returns 200 with empty articles array when no articles exist', async () => {
    const res = await request(app).get('/api/articles');
    expect(res.status).toBe(200);
    expect(res.body.articles).toEqual([]);
    expect(res.body.articlesCount).toBe(0);
  });

  it('returns articles with correct shape and no body field', async () => {
    const token = await registerAndGetToken(ALICE);
    await createArticle(token);

    const res = await request(app).get('/api/articles');
    expect(res.status).toBe(200);
    expect(res.body.articles).toHaveLength(1);
    expect(res.body.articlesCount).toBe(1);

    const article = res.body.articles[0];
    expect(article).toHaveProperty('slug');
    expect(article).toHaveProperty('title', ARTICLE_PAYLOAD.title);
    expect(article).toHaveProperty('description', ARTICLE_PAYLOAD.description);
    expect(article).not.toHaveProperty('body');
    expect(article).toHaveProperty('tagList');
    expect(article).toHaveProperty('favorited');
    expect(article).toHaveProperty('favoritesCount');
    expect(article).toHaveProperty('author');
  });

  it('filters by tag', async () => {
    const token = await registerAndGetToken(ALICE);
    await createArticle(token, { ...ARTICLE_PAYLOAD, tagList: ['dragons'] });
    await createArticle(token, { ...ARTICLE_PAYLOAD, title: 'Fish Tales', tagList: ['fish'] });

    const res = await request(app).get('/api/articles?tag=dragons');
    expect(res.status).toBe(200);
    expect(res.body.articles).toHaveLength(1);
    expect(res.body.articles[0].tagList).toContain('dragons');
  });

  it('filters by author', async () => {
    const aliceToken = await registerAndGetToken(ALICE);
    const bobToken = await registerAndGetToken(BOB);
    await createArticle(aliceToken, { ...ARTICLE_PAYLOAD, title: "Alice's Article" });
    await createArticle(bobToken, { ...ARTICLE_PAYLOAD, title: "Bob's Article" });

    const res = await request(app).get('/api/articles?author=alice');
    expect(res.status).toBe(200);
    expect(res.body.articles).toHaveLength(1);
    expect(res.body.articles[0].author.username).toBe('alice');
  });

  it('respects limit and offset for pagination', async () => {
    const token = await registerAndGetToken(ALICE);
    for (let i = 1; i <= 5; i++) {
      await createArticle(token, { ...ARTICLE_PAYLOAD, title: `Article ${i}` });
    }

    const res = await request(app).get('/api/articles?limit=2&offset=1');
    expect(res.status).toBe(200);
    expect(res.body.articles).toHaveLength(2);
    expect(res.body.articlesCount).toBe(5); // total, not page size
  });

  it('returns favorited true for authenticated user who favorited the article', async () => {
    const aliceToken = await registerAndGetToken(ALICE);
    const bobToken = await registerAndGetToken(BOB);
    const slug = await createArticle(aliceToken);

    await request(app)
      .post(`/api/articles/${slug}/favorite`)
      .set('Authorization', `Token ${bobToken}`);

    const res = await request(app)
      .get('/api/articles')
      .set('Authorization', `Token ${bobToken}`);
    expect(res.status).toBe(200);
    expect(res.body.articles[0].favorited).toBe(true);
  });
});

