      description: z.string().optional(),
      body: z.string().optional(),
      tagList: z.array(z.string()).optional(),
    })
    .refine((data) => Object.values(data).some((v) => v !== undefined), {
      message: 'no fields provided',
    }),
});

const ArticleQuerySchema = z.object({
  tag: z.string().optional(),
  author: z.string().optional(),
  favorited: z.string().optional(),
  limit: z.coerce.number().int().min(1).max(100).optional(),
  offset: z.coerce.number().int().min(0).optional(),
});

const FeedQuerySchema = z.object({
  limit: z.coerce.number().int().min(1).max(100).optional(),
  offset: z.coerce.number().int().min(0).optional(),
});

// =============================================================================
// Response helpers
// =============================================================================

/** ┬º┬º Spec change 2024-08-16: list endpoints omit `body` for performance. */
type ArticleListItem = Omit<Article, 'body'>;

function toListItem(article: Article): ArticleListItem {
  // Destructure to explicitly discard body ΓÇö _body prefix suppresses noUnusedLocals
  const { body: _body, ...rest } = article;
  return rest;
}

// =============================================================================
// Router factory
// =============================================================================

/**
 * Factory that constructs the articles router with injected service dependency.
 *
 * Routes:
 *   GET    /articles                     ΓÇö list articles (auth optional)
 *   GET    /articles/feed                ΓÇö personalized feed (auth required)
 *   GET    /articles/:slug               ΓÇö single article (auth optional)
 *   POST   /articles                     ΓÇö create article (auth required)
 *   PUT    /articles/:slug               ΓÇö update article (auth required, author only)
 *   DELETE /articles/:slug               ΓÇö delete article (auth required, author only)
 *   POST   /articles/:slug/favorite      ΓÇö favorite article (auth required)
 *   DELETE /articles/:slug/favorite      ΓÇö unfavorite article (auth required)
 *
 * @param articleService - Injected article business-logic service
 * @returns Configured Express Router
 */
export function createArticleRouter(articleService: ArticleService): Router {
  const router = Router();

  // GET /api/articles/feed ΓÇö personalized feed (must be registered before /:slug)
  router.get(
    '/articles/feed',
    requireAuth,
    asyncHandler(async (req, res) => {
      const parsed = FeedQuerySchema.safeParse(req.query);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const result = await articleService.getFeed(req.userId!, parsed.data);
      res.status(200).json({
        articles: result.articles.map(toListItem),
        articlesCount: result.articlesCount,
      });
    }),
  );

  // GET /api/articles ΓÇö list articles with optional filters
  router.get(
    '/articles',
    optionalAuth,
    asyncHandler(async (req, res) => {
      const parsed = ArticleQuerySchema.safeParse(req.query);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const { tag, author, favorited, limit, offset } = parsed.data;
      const result = await articleService.listArticles(
        { tag, author, favorited },
        { limit, offset },
        req.userId,
      );
      res.status(200).json({
        articles: result.articles.map(toListItem),
        articlesCount: result.articlesCount,
      });
    }),
  );

  // GET /api/articles/:slug ΓÇö single article
  router.get(
    '/articles/:slug',
    optionalAuth,
    asyncHandler(async (req, res) => {
      const article = await articleService.getArticle(req.params.slug, req.userId);
      res.status(200).json({ article });
    }),
  );

  // POST /api/articles ΓÇö create article
  router.post(
    '/articles',
    requireAuth,
    asyncHandler(async (req, res) => {
      const parsed = CreateArticleSchema.safeParse(req.body);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const article = await articleService.createArticle(req.userId!, parsed.data.article);
      res.status(201).json({ article });
    }),
  );

  // PUT /api/articles/:slug ΓÇö update article (author only)
  router.put(
    '/articles/:slug',
    requireAuth,
    asyncHandler(async (req, res) => {
      const parsed = UpdateArticleSchema.safeParse(req.body);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const article = await articleService.updateArticle(
        req.params.slug,
        req.userId!,
        parsed.data.article,
      );
      res.status(200).json({ article });
    }),
  );

  // DELETE /api/articles/:slug ΓÇö delete article (author only)
  router.delete(
    '/articles/:slug',
    requireAuth,
    asyncHandler(async (req, res) => {
      await articleService.deleteArticle(req.params.slug, req.userId!);
      res.status(204).send();
    }),
  );

  // POST /api/articles/:slug/favorite ΓÇö favorite article
  router.post(
    '/articles/:slug/favorite',
    requireAuth,
    asyncHandler(async (req, res) => {
      const article = await articleService.favoriteArticle(req.userId!, req.params.slug);
      res.status(200).json({ article });
    }),
  );

  // DELETE /api/articles/:slug/favorite ΓÇö unfavorite article
  router.delete(
    '/articles/:slug/favorite',
    requireAuth,
    asyncHandler(async (req, res) => {
      const article = await articleService.unfavoriteArticle(req.userId!, req.params.slug);
      res.status(200).json({ article });
    }),
  );

  return router;
}

import request from 'supertest';
import { createApp } from '../app';
import { InMemoryUserRepository } from '../repositories/InMemoryUserRepository';
import { InMemoryProfileRepository } from '../repositories/InMemoryProfileRepository';
import { InMemoryArticleRepository } from '../repositories/InMemoryArticleRepository';
import { InMemoryCommentRepository } from '../repositories/InMemoryCommentRepository';
import { InMemoryTagRepository } from '../repositories/InMemoryTagRepository';
import { UserService } from '../services/UserService';
import { ProfileService } from '../services/ProfileService';
import { ArticleService } from '../services/ArticleService';
import { CommentService } from '../services/CommentService';
import { TagService } from '../services/TagService';

// Shared user store ΓÇö all repos that need user lookups reference this instance.
const userRepo = new InMemoryUserRepository();
const profileRepo = new InMemoryProfileRepository(userRepo);
const articleRepo = new InMemoryArticleRepository(userRepo);
const commentRepo = new InMemoryCommentRepository(userRepo);
const tagRepo = new InMemoryTagRepository(articleRepo);

const userService = new UserService(userRepo);
const profileService = new ProfileService(profileRepo);
const articleService = new ArticleService(articleRepo);
const commentService = new CommentService(commentRepo, articleRepo);
const tagService = new TagService(tagRepo);
const app = createApp({ userService, profileService, articleService, commentService, tagService });

const ALICE = { email: 'alice@example.com', username: 'alice', password: 'Password123!' };
const BOB = { email: 'bob@example.com', username: 'bob', password: 'Password123!' };

const ARTICLE_PAYLOAD = {
  title: 'Test Article',
  description: 'A test article',
  body: 'Article body content',
  tagList: [],
};

/** Register a user and return their JWT token. */
async function registerAndGetToken(user: typeof ALICE): Promise<string> {
  const res = await request(app).post('/api/users').send({ user });
  return res.body.user.token as string;
}

/** Create an article and return its slug. */
async function createArticle(token: string): Promise<string> {
  const res = await request(app)
    .post('/api/articles')
    .set('Authorization', `Token ${token}`)
    .send({ article: ARTICLE_PAYLOAD });
  return res.body.article.slug as string;
}

/** Add a comment and return its id. */
async function addComment(token: string, slug: string, body = 'A test comment'): Promise<number> {
  const res = await request(app)
    .post(`/api/articles/${slug}/comments`)
    .set('Authorization', `Token ${token}`)
    .send({ comment: { body } });
  return res.body.comment.id as number;
}

beforeEach(() => {
  userRepo.clear();
  profileRepo.clear();
  articleRepo.clear();
  commentRepo.clear();
});

// =============================================================================
// GET /api/articles/:slug/comments
// =============================================================================
describe('GET /api/articles/:slug/comments', () => {
  it('returns 200 with empty comments array when article has no comments', async () => {
    const token = await registerAndGetToken(ALICE);
    const slug = await createArticle(token);

    const res = await request(app).get(`/api/articles/${slug}/comments`);
    expect(res.status).toBe(200);
    expect(res.body.comments).toEqual([]);
  });

  it('returns 200 with correct comment shape', async () => {
    const token = await registerAndGetToken(ALICE);
    const slug = await createArticle(token);
    await addComment(token, slug, 'Hello world');

    const res = await request(app).get(`/api/articles/${slug}/comments`);
    expect(res.status).toBe(200);
    expect(res.body.comments).toHaveLength(1);

    const comment = res.body.comments[0];
    expect(comment).toHaveProperty('id');
    expect(comment).toHaveProperty('body', 'Hello world');
    expect(comment).toHaveProperty('createdAt');
    expect(comment).toHaveProperty('updatedAt');
    expect(comment).toHaveProperty('author');
    expect(comment.author).toHaveProperty('username', 'alice');
    expect(comment.author).toHaveProperty('bio');
    expect(comment.author).toHaveProperty('image');
    expect(comment.author).toHaveProperty('following');
  });

  it('returns 404 when article does not exist', async () => {
    const res = await request(app).get('/api/articles/no-such-article/comments');
    expect(res.status).toBe(404);
    expect(res.body.errors).toHaveProperty('article');
  });

  it('returns comments without auth (auth optional)', async () => {
    const token = await registerAndGetToken(ALICE);
    const slug = await createArticle(token);
    await addComment(token, slug, 'Public comment');

    const res = await request(app).get(`/api/articles/${slug}/comments`);
    expect(res.status).toBe(200);
    expect(res.body.comments).toHaveLength(1);
  });

  it('returns multiple comments ordered by creation date descending', async () => {
    const token = await registerAndGetToken(ALICE);
    const slug = await createArticle(token);
    await addComment(token, slug, 'First comment');
    await addComment(token, slug, 'Second comment');
    await addComment(token, slug, 'Third comment');

    const res = await request(app).get(`/api/articles/${slug}/comments`);
    expect(res.status).toBe(200);
    expect(res.body.comments).toHaveLength(3);
    // Most recent first
    const dates = res.body.comments.map((c: { createdAt: string }) => new Date(c.createdAt).getTime());
    expect(dates[0]).toBeGreaterThanOrEqual(dates[1]);
    expect(dates[1]).toBeGreaterThanOrEqual(dates[2]);
  });
});

