    expect(res.status).toBe(401);
  });
});

// =============================================================================
// PUT /api/user ΓÇö update current user
// =============================================================================
describe('PUT /api/user', () => {
  let token: string;

  beforeEach(async () => {
    const res = await request(app).post('/api/users').send({ user: SEED });
    token = res.body.user.token as string;
  });

  it('returns 200 with updated user when bio is changed', async () => {
    const res = await request(app)
      .put('/api/user')
      .set('Authorization', `Token ${token}`)
      .send({ user: { bio: 'Hello world' } });

    expect(res.status).toBe(200);
    expect(res.body.user.bio).toBe('Hello world');
  });

  it('coerces empty string bio to null in response (┬º10)', async () => {
    const res = await request(app)
      .put('/api/user')
      .set('Authorization', `Token ${token}`)
      .send({ user: { bio: '' } });

    expect(res.status).toBe(200);
    expect(res.body.user.bio).toBeNull();
  });

  it('returns 401 when Authorization header is missing', async () => {
    const res = await request(app).put('/api/user').send({ user: { bio: 'test' } });

    expect(res.status).toBe(401);
  });

  it('returns 422 when update body has no recognized fields', async () => {
    const res = await request(app)
      .put('/api/user')
      .set('Authorization', `Token ${token}`)
      .send({ user: {} });

    expect(res.status).toBe(422);
  });

  it('returns 409 when new email is already taken', async () => {
    await request(app)
      .post('/api/users')
      .send({ user: { email: 'other@example.com', username: 'other', password: SEED.password } });

    const res = await request(app)
      .put('/api/user')
      .set('Authorization', `Token ${token}`)
      .send({ user: { email: 'other@example.com' } });

    expect(res.status).toBe(409);
    expect(res.body.errors).toHaveProperty('email');
  });
});

import { Router } from 'express';
import { z } from 'zod';
import type { UserService } from '../services/UserService';
import { requireAuth } from '../middleware/auth';
import { asyncHandler } from '../utils/asyncHandler';
import { zodToValidationError } from '../utils/zodError';

/** Zod schema for POST /api/users (registration). */
const RegisterSchema = z.object({
  user: z.object({
    email: z.string().min(1, "can't be blank").email('is invalid'),
    username: z.string().min(1, "can't be blank"),
    password: z.string().min(1, "can't be blank"),
  }),
});

/** Zod schema for POST /api/users/login. */
const LoginSchema = z.object({
  user: z.object({
    email: z.string().min(1, "can't be blank"),
    password: z.string().min(1, "can't be blank"),
  }),
});

/** Zod schema for PUT /api/user (partial update ΓÇö all fields optional). */
const UpdateUserSchema = z.object({
  user: z
    .object({
      email: z.string().min(1, "can't be blank").email('is invalid').optional(),
      username: z.string().min(1, "can't be blank").optional(),
      password: z.string().optional(),
      bio: z.string().nullable().optional(),
      image: z.string().nullable().optional(),
    })
    .refine((u) => Object.keys(u).length > 0, { message: 'no fields provided' }),
});


/**
 * Factory that constructs the user router with injected service dependency.
 *
 * Routes:
 *   POST   /users         ΓÇö register a new user
 *   POST   /users/login   ΓÇö authenticate with email + password
 *   GET    /user          ΓÇö get the current authenticated user
 *   PUT    /user          ΓÇö update the current authenticated user
 *
 * @param userService - Injected user business-logic service
 * @returns Configured Express Router
 */
export function createUserRouter(userService: UserService): Router {
  const router = Router();

  // POST /api/users ΓÇö register
  router.post(
    '/users',
    asyncHandler(async (req, res) => {
      const parsed = RegisterSchema.safeParse(req.body);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const response = await userService.register(parsed.data.user);
      res.status(201).json({ user: response });
    }),
  );

  // POST /api/users/login ΓÇö login
  router.post(
    '/users/login',
    asyncHandler(async (req, res) => {
      const parsed = LoginSchema.safeParse(req.body);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const response = await userService.login(parsed.data.user);
      res.status(200).json({ user: response });
    }),
  );

  // GET /api/user ΓÇö get current user (auth required)
  router.get(
    '/user',
    requireAuth,
    asyncHandler(async (req, res) => {
      // requireAuth guarantees userId is set; non-null assertion is safe here
      const response = await userService.getCurrentUser(req.userId!);
      res.status(200).json({ user: response });
    }),
  );

  // PUT /api/user ΓÇö update current user (auth required)
  router.put(
    '/user',
    requireAuth,
    asyncHandler(async (req, res) => {
      const parsed = UpdateUserSchema.safeParse(req.body);
      if (!parsed.success) throw zodToValidationError(parsed.error);
      const response = await userService.updateUser(req.userId!, parsed.data.user);
      res.status(200).json({ user: response });
    }),
  );

  return router;
}

import { PrismaClient } from '@prisma/client';
import { createApp } from './app';
import { PrismaUserRepository } from './repositories/PrismaUserRepository';
import { PrismaProfileRepository } from './repositories/PrismaProfileRepository';
import { PrismaArticleRepository } from './repositories/PrismaArticleRepository';
import { PrismaCommentRepository } from './repositories/PrismaCommentRepository';
import { PrismaTagRepository } from './repositories/PrismaTagRepository';
import { UserService } from './services/UserService';
import { ProfileService } from './services/ProfileService';
import { ArticleService } from './services/ArticleService';
import { CommentService } from './services/CommentService';
import { TagService } from './services/TagService';

// ┬º4 Named constant ΓÇö minimum secret length is a security requirement, not a magic number
const MIN_JWT_SECRET_LENGTH = 32;

/**
 * Startup validation: fail fast if required configuration is absent or invalid.
 * A server that starts with a weak JWT secret is a security defect, not a runtime error.
 */
const jwtSecret = process.env.JWT_SECRET;
if (!jwtSecret || jwtSecret.length < MIN_JWT_SECRET_LENGTH) {
  console.error(
    `FATAL: JWT_SECRET must be at least ${MIN_JWT_SECRET_LENGTH} characters. ` +
      'Set it via environment variable or .env file.',
  );
  process.exit(1);
}

const PORT = parseInt(process.env.PORT ?? '3000', 10);

// Composition root: wire concrete implementations to port interfaces
const prisma = new PrismaClient();
const userRepository = new PrismaUserRepository(prisma);
const profileRepository = new PrismaProfileRepository(prisma);
const articleRepository = new PrismaArticleRepository(prisma);
const commentRepository = new PrismaCommentRepository(prisma);
const tagRepository = new PrismaTagRepository(prisma);
const userService = new UserService(userRepository);
const profileService = new ProfileService(profileRepository);
const articleService = new ArticleService(articleRepository);
const commentService = new CommentService(commentRepository, articleRepository);
const tagService = new TagService(tagRepository);

const app = createApp({ userService, profileService, articleService, commentService, tagService });

const server = app.listen(PORT, () => {
  console.log(`Conduit API server listening on port ${PORT}`);
});

// Graceful shutdown: close HTTP server before disconnecting the database pool
process.on('SIGTERM', () => {
  server.close(() => {
    prisma.$disconnect().catch(console.error);
    process.exit(0);
  });
});

import { ArticleService } from './ArticleService';
import { InMemoryArticleRepository } from '../repositories/InMemoryArticleRepository';
import { ForbiddenError, NotFoundError } from '../errors/AppError';
import type { Article } from '../types/domain';

/** Build a minimal Article fixture for seeding the in-memory repository. */
function makeArticle(overrides: Partial<Article> = {}): Article {
  return {
    id: 1,
    slug: 'test-slug',
    title: 'Test Title',
    description: 'Test description',
    body: 'Test body',
    authorId: 10,
    author: { username: 'author', bio: null, image: null, following: false },
    tagList: ['test'],
    favoritesCount: 0,
    favorited: false,
    createdAt: new Date('2024-01-01'),
    updatedAt: new Date('2024-01-01'),
    ...overrides,
  };
}

describe('ArticleService', () => {
  let repo: InMemoryArticleRepository;
  let service: ArticleService;

  beforeEach(() => {
    repo = new InMemoryArticleRepository();
    service = new ArticleService(repo);
  });

  // ===========================================================================
  // getArticle
  // ===========================================================================
  describe('getArticle', () => {
    it('returns the article when it exists', async () => {
      repo.seed([makeArticle()]);
      const article = await service.getArticle('test-slug');
      expect(article.slug).toBe('test-slug');
    });

    it('throws NotFoundError when article does not exist', async () => {
      await expect(service.getArticle('nonexistent')).rejects.toThrow(NotFoundError);
    });

    it('returns article with favorited=true for user who has favorited', async () => {
      repo.seed([makeArticle()]);
      await repo.addFavorite(99, 'test-slug');
      const article = await service.getArticle('test-slug', 99);
      expect(article.favorited).toBe(true);
    });
  });

  // ===========================================================================
  // listArticles
  // ===========================================================================
  describe('listArticles', () => {
    it('returns all articles with default pagination', async () => {
      repo.seed([makeArticle({ id: 1, slug: 'a' }), makeArticle({ id: 2, slug: 'b' })]);
      const result = await service.listArticles({}, {});
      expect(result.articlesCount).toBe(2);
      expect(result.articles).toHaveLength(2);
    });

    it('respects limit and offset', async () => {
      repo.seed([
        makeArticle({ id: 1, slug: 'a', createdAt: new Date('2024-01-03') }),
        makeArticle({ id: 2, slug: 'b', createdAt: new Date('2024-01-02') }),
        makeArticle({ id: 3, slug: 'c', createdAt: new Date('2024-01-01') }),
      ]);
      const result = await service.listArticles({}, { limit: 1, offset: 1 });
      expect(result.articles).toHaveLength(1);
      expect(result.articles[0].slug).toBe('b');
    });

    it('filters by tag', async () => {
      repo.seed([
        makeArticle({ id: 1, slug: 'a', tagList: ['dragons'] }),
        makeArticle({ id: 2, slug: 'b', tagList: ['fish'] }),
      ]);
      const result = await service.listArticles({ tag: 'dragons' }, {});
      expect(result.articlesCount).toBe(1);
      expect(result.articles[0].tagList).toContain('dragons');
    });

    it('filters by author username', async () => {
      repo.seed([
        makeArticle({
          id: 1,
          slug: 'a',
          author: { username: 'alice', bio: null, image: null, following: false },
        }),
        makeArticle({
          id: 2,
          slug: 'b',
          author: { username: 'bob', bio: null, image: null, following: false },
        }),
      ]);
      const result = await service.listArticles({ author: 'alice' }, {});
      expect(result.articlesCount).toBe(1);
      expect(result.articles[0].author.username).toBe('alice');
    });
  });

  // ===========================================================================
  // createArticle
  // ===========================================================================
  describe('createArticle', () => {
    it('creates article with given data and returns it', async () => {
      const article = await service.createArticle(1, {
        title: 'New Article',
        description: 'Desc',
        body: 'Body',
        tagList: ['tag1'],
      });
      expect(article.title).toBe('New Article');
      expect(article.tagList).toEqual(['tag1']);
      expect(article.favorited).toBe(false);
      expect(article.favoritesCount).toBe(0);
    });
  });

  // ===========================================================================
  // updateArticle
  // ===========================================================================
  describe('updateArticle', () => {
    it('throws NotFoundError when article does not exist', async () => {
      await expect(service.updateArticle('nonexistent', 10, { title: 'x' })).rejects.toThrow(
        NotFoundError,
      );
    });

    it('throws ForbiddenError when user is not the author', async () => {
      repo.seed([makeArticle({ authorId: 10 })]);
      await expect(service.updateArticle('test-slug', 99, { title: 'x' })).rejects.toThrow(
        ForbiddenError,
      );
    });

    it('updates article successfully when user is the author', async () => {
      repo.seed([makeArticle({ authorId: 10 })]);
      const updated = await service.updateArticle('test-slug', 10, { title: 'Updated' });
      expect(updated.title).toBe('Updated');
    });

    it('returns 404 before 403 ΓÇö checks existence before authorization', async () => {
      // Nonexistent slug must throw NotFoundError, not ForbiddenError, regardless of userId
      await expect(service.updateArticle('ghost', 10, { title: 'x' })).rejects.toThrow(
        NotFoundError,
      );
    });
  });

  // ===========================================================================
  // deleteArticle
  // ===========================================================================
  describe('deleteArticle', () => {
    it('throws NotFoundError when article does not exist', async () => {
      await expect(service.deleteArticle('nonexistent', 10)).rejects.toThrow(NotFoundError);
    });

    it('throws ForbiddenError when user is not the author', async () => {
      repo.seed([makeArticle({ authorId: 10 })]);
      await expect(service.deleteArticle('test-slug', 99)).rejects.toThrow(ForbiddenError);
    });

    it('deletes article successfully when user is the author', async () => {
      repo.seed([makeArticle({ authorId: 10 })]);
      await service.deleteArticle('test-slug', 10);
      await expect(service.getArticle('test-slug')).rejects.toThrow(NotFoundError);
    });
  });

  // ===========================================================================
  // favoriteArticle
  // ===========================================================================
  describe('favoriteArticle', () => {
    it('returns article with favorited: true', async () => {
      repo.seed([makeArticle()]);
      const article = await service.favoriteArticle(99, 'test-slug');
      expect(article.favorited).toBe(true);
      expect(article.favoritesCount).toBe(1);
    });

    it('throws NotFoundError when article does not exist', async () => {
      await expect(service.favoriteArticle(1, 'ghost')).rejects.toThrow(NotFoundError);
    });
  });

  // ===========================================================================
  // unfavoriteArticle
  // ===========================================================================
  describe('unfavoriteArticle', () => {
    it('returns article with favorited: false after unfavorite', async () => {
      repo.seed([makeArticle()]);
      await service.favoriteArticle(99, 'test-slug');
      const article = await service.unfavoriteArticle(99, 'test-slug');
      expect(article.favorited).toBe(false);
      expect(article.favoritesCount).toBe(0);
    });

    it('throws NotFoundError when article does not exist', async () => {
      await expect(service.unfavoriteArticle(1, 'ghost')).rejects.toThrow(NotFoundError);
    });
  });

  // ===========================================================================
  // getFeed
  // ===========================================================================
  describe('getFeed', () => {
    it('returns articles with default pagination', async () => {
      repo.seed([makeArticle()]);
      const result = await service.getFeed(1, {});
      expect(result.articlesCount).toBe(1);
    });
  });
});

