      articleRepo.seed([makeArticle()]);
      await service.addComment(20, 'test-slug', 'Hello world');
      const comments = await service.getComments('test-slug');
      expect(comments).toHaveLength(1);
      expect(comments[0].body).toBe('Hello world');
    });
  });

  // ===========================================================================
  // deleteComment
  // ===========================================================================
  describe('deleteComment', () => {
    it('throws NotFoundError when article does not exist', async () => {
      await expect(service.deleteComment(20, 'nonexistent', 1)).rejects.toThrow(NotFoundError);
    });

    it('throws NotFoundError when comment does not exist', async () => {
      articleRepo.seed([makeArticle()]);
      await expect(service.deleteComment(20, 'test-slug', 999)).rejects.toThrow(NotFoundError);
    });

    it('throws ForbiddenError when user is not the comment author', async () => {
      articleRepo.seed([makeArticle()]);
      commentRepo.seed({ 'test-slug': [makeComment({ id: 1, authorId: 20 })] });
      await expect(service.deleteComment(99, 'test-slug', 1)).rejects.toThrow(ForbiddenError);
    });

    it('deletes the comment when user is the author', async () => {
      articleRepo.seed([makeArticle()]);
      commentRepo.seed({ 'test-slug': [makeComment({ id: 1, authorId: 20 })] });
      await expect(service.deleteComment(20, 'test-slug', 1)).resolves.toBeUndefined();
      const comments = await service.getComments('test-slug');
      expect(comments).toHaveLength(0);
    });

    it('checks article existence before comment existence', async () => {
      // Article does not exist; should throw NotFoundError for 'article', not 'comment'
      const error = await service.deleteComment(20, 'no-such-article', 1).catch((e) => e);
      expect(error).toBeInstanceOf(NotFoundError);
      expect((error as NotFoundError).resource).toBe('article');
    });

    it('throws NotFoundError with resource=comment when comment missing', async () => {
      articleRepo.seed([makeArticle()]);
      const error = await service.deleteComment(20, 'test-slug', 999).catch((e) => e);
      expect(error).toBeInstanceOf(NotFoundError);
      expect((error as NotFoundError).resource).toBe('comment');
    });
  });
});

import { UserService } from './UserService';
import { InMemoryUserRepository } from '../repositories/InMemoryUserRepository';
import { ConflictError, AppError, NotFoundError } from '../errors/AppError';

const TEST_EMAIL = 'alice@example.com';
const TEST_USERNAME = 'alice';
const TEST_PASSWORD = 'password123';

describe('UserService', () => {
  let repo: InMemoryUserRepository;
  let service: UserService;

  beforeEach(() => {
    repo = new InMemoryUserRepository();
    service = new UserService(repo);
  });

  // ---------------------------------------------------------------------------
  // register
  // ---------------------------------------------------------------------------
  describe('register', () => {
    it('returns authenticated user response on successful registration', async () => {
      const result = await service.register({
        email: TEST_EMAIL,
        username: TEST_USERNAME,
        password: TEST_PASSWORD,
      });

      expect(result.email).toBe(TEST_EMAIL);
      expect(result.username).toBe(TEST_USERNAME);
      expect(result.bio).toBeNull();
      expect(result.image).toBeNull();
      expect(typeof result.token).toBe('string');
      expect(result.token.length).toBeGreaterThan(0);
    });

    it('stores email as lowercase', async () => {
      const result = await service.register({
        email: 'Alice@Example.COM',
        username: TEST_USERNAME,
        password: TEST_PASSWORD,
      });
      expect(result.email).toBe('alice@example.com');
    });

    it('throws ConflictError when email is already registered', async () => {
      await service.register({ email: TEST_EMAIL, username: TEST_USERNAME, password: TEST_PASSWORD });

      await expect(
        service.register({ email: TEST_EMAIL, username: 'bob', password: TEST_PASSWORD }),
      ).rejects.toThrow(ConflictError);
    });

    it('throws ConflictError when username is already taken', async () => {
      await service.register({ email: TEST_EMAIL, username: TEST_USERNAME, password: TEST_PASSWORD });

      await expect(
        service.register({ email: 'bob@example.com', username: TEST_USERNAME, password: TEST_PASSWORD }),
      ).rejects.toThrow(ConflictError);
    });

    it('does not store plaintext password', async () => {
      await service.register({ email: TEST_EMAIL, username: TEST_USERNAME, password: TEST_PASSWORD });
      const stored = await repo.findByEmail(TEST_EMAIL);
      expect(stored?.passwordHash).not.toBe(TEST_PASSWORD);
      expect(stored?.passwordHash).toMatch(/^\$argon2/);
    });
  });

  // ---------------------------------------------------------------------------
  // login
  // ---------------------------------------------------------------------------
  describe('login', () => {
    beforeEach(async () => {
      await service.register({ email: TEST_EMAIL, username: TEST_USERNAME, password: TEST_PASSWORD });
    });

    it('returns authenticated user response for valid credentials', async () => {
      const result = await service.login({ email: TEST_EMAIL, password: TEST_PASSWORD });

      expect(result.email).toBe(TEST_EMAIL);
      expect(result.username).toBe(TEST_USERNAME);
      expect(typeof result.token).toBe('string');
    });

    it('throws AppError (401) for unknown email', async () => {
      await expect(
        service.login({ email: 'unknown@example.com', password: TEST_PASSWORD }),
      ).rejects.toThrow(AppError);
    });

    it('throws AppError (401) for wrong password', async () => {
      await expect(
        service.login({ email: TEST_EMAIL, password: 'wrong-password' }),
      ).rejects.toThrow(AppError);
    });

    it('returns 401 with credentials key for invalid login', async () => {
      await expect(
        service.login({ email: TEST_EMAIL, password: 'wrong-password' }),
      ).rejects.toMatchObject({ statusCode: 401, resource: 'credentials', message: 'invalid' });
    });
  });

  // ---------------------------------------------------------------------------
  // getCurrentUser
  // ---------------------------------------------------------------------------
  describe('getCurrentUser', () => {
    it('returns authenticated response for existing user', async () => {
      const registered = await service.register({
        email: TEST_EMAIL,
        username: TEST_USERNAME,
        password: TEST_PASSWORD,
      });
      const stored = await repo.findByEmail(TEST_EMAIL);
      const result = await service.getCurrentUser(stored!.id);

      expect(result.email).toBe(registered.email);
      expect(result.username).toBe(registered.username);
      expect(typeof result.token).toBe('string');
    });

    it('throws NotFoundError for non-existent user id', async () => {
      await expect(service.getCurrentUser(9999)).rejects.toThrow(NotFoundError);
    });
  });

  // ---------------------------------------------------------------------------
  // updateUser
  // ---------------------------------------------------------------------------
  describe('updateUser', () => {
    let userId: number;

    beforeEach(async () => {
      await service.register({ email: TEST_EMAIL, username: TEST_USERNAME, password: TEST_PASSWORD });
      const stored = await repo.findByEmail(TEST_EMAIL);
      userId = stored!.id;
    });

    it('updates email and returns updated response', async () => {
      const result = await service.updateUser(userId, { email: 'newalice@example.com' });
      expect(result.email).toBe('newalice@example.com');
    });

    it('coerces empty string bio to null (┬º10 nullable field coercion)', async () => {
      const result = await service.updateUser(userId, { bio: '' });
      expect(result.bio).toBeNull();
    });

    it('coerces empty string image to null (┬º10 nullable field coercion)', async () => {
      const result = await service.updateUser(userId, { image: '' });
      expect(result.image).toBeNull();
    });

    it('stores non-empty bio string as-is', async () => {
      const result = await service.updateUser(userId, { bio: 'I write code.' });
      expect(result.bio).toBe('I write code.');
    });

    it('throws ConflictError when new email is already taken', async () => {
      await service.register({ email: 'bob@example.com', username: 'bob', password: TEST_PASSWORD });
      await expect(
        service.updateUser(userId, { email: 'bob@example.com' }),
      ).rejects.toThrow(ConflictError);
    });

    it('throws NotFoundError for non-existent user id', async () => {
      await expect(service.updateUser(9999, { bio: 'hello' })).rejects.toThrow(NotFoundError);
    });
  });
});

import { hash as hashPassword, verify as verifyPassword } from 'argon2';
import pkg from 'jsonwebtoken';
import type { SignOptions } from 'jsonwebtoken';
import type { IUserRepository } from '../repositories/IUserRepository';
import type { User, UpdateUserData } from '../types/domain';
import { NotFoundError, InvalidCredentialsError } from '../errors/AppError';

// ┬º11 ESM-safe import: jsonwebtoken is CJS ΓÇö use default import + destructure
const { sign } = pkg;

// ┬º4 Named constants ΓÇö no magic values inline
// ┬ºCLAUDE.md ┬º Known Type Pitfalls: cast via SignOptions['expiresIn'] to satisfy branded type
const JWT_SECRET = process.env.JWT_SECRET ?? '';
const JWT_EXPIRY = (process.env.JWT_EXPIRY ?? '7d') as SignOptions['expiresIn'];

/** Response DTO for all authenticated user endpoints. */
export interface AuthenticatedUserResponse {
  email: string;
  token: string;
  username: string;
  bio: string | null;
  image: string | null;
}

/** Input for user registration. */
export interface RegisterInput {
  email: string;
  username: string;
  password: string;
}

/** Input for user login. */
export interface LoginInput {
  email: string;
  password: string;
}

/** Input for updating the current user's profile. All fields are optional. */
export interface UpdateUserInput {
  email?: string;
  username?: string;
  password?: string;
  bio?: string | null;
  image?: string | null;
}

/**
 * Business logic for user authentication and profile management.
 *
 * Depends on `IUserRepository` via constructor injection ΓÇö no direct Prisma imports.
 * Wire concrete implementations at the composition root (`src/server.ts`).
 */
export class UserService {
  constructor(private readonly userRepository: IUserRepository) {}

  /**
   * Register a new user account and return an authenticated response.
   *
   * @param input - Registration payload (email, username, plaintext password)
   * @returns Authenticated user response with signed JWT
   * @throws `ConflictError` if email or username is already taken
   */
  async register(input: RegisterInput): Promise<AuthenticatedUserResponse> {
    const passwordHash = await hashPassword(input.password);
    const user = await this.userRepository.create({
      email: input.email,
      username: input.username,
      passwordHash,
    });
    return this.buildAuthResponse(user);
  }

  /**
   * Authenticate a user with email and password.
   *
   * Returns the same error for unknown email and wrong password to prevent
   * user enumeration via timing or message differences.
   *
   * @param input - Login credentials (email, plaintext password)
   * @returns Authenticated user response with signed JWT
   * @throws `ValidationError` if credentials are invalid
   */
  async login(input: LoginInput): Promise<AuthenticatedUserResponse> {
    const user = await this.userRepository.findByEmail(input.email);
    if (!user) throw new InvalidCredentialsError();
    const valid = await verifyPassword(user.passwordHash, input.password);
    if (!valid) throw new InvalidCredentialsError();
    return this.buildAuthResponse(user);
  }

  /**
   * Retrieve the currently authenticated user.
   *
   * @param userId - The authenticated user's numeric ID (from JWT payload)
   * @returns Authenticated user response with a fresh signed JWT
   * @throws `NotFoundError` if the user no longer exists
   */
  async getCurrentUser(userId: number): Promise<AuthenticatedUserResponse> {
    const user = await this.userRepository.findById(userId);
    if (!user) throw new NotFoundError('user');
    return this.buildAuthResponse(user);
  }

  /**
   * Update the current user's profile fields.
   *
   * ┬º10 Nullable field coercion: empty string for `bio` or `image` is coerced to null
   * per the Conduit contract ΓÇö `PUT /api/user` with `bio: ""` must return `bio: null`.
   *
   * @param userId - The authenticated user's numeric ID
   * @param input - Partial update payload
   * @returns Updated authenticated user response with a fresh signed JWT
   * @throws `NotFoundError` if the user no longer exists
   * @throws `ConflictError` if the new email or username is already taken
   */
  async updateUser(userId: number, input: UpdateUserInput): Promise<AuthenticatedUserResponse> {
    const patch: UpdateUserData = {};
    if (input.email !== undefined) patch.email = input.email;
    if (input.username !== undefined) patch.username = input.username;
    if (input.password !== undefined) patch.passwordHash = await hashPassword(input.password);
    // ┬º10: coerce empty string ΓåÆ null for nullable string fields
    if (input.bio !== undefined) patch.bio = input.bio === '' ? null : input.bio;
    if (input.image !== undefined) patch.image = input.image === '' ? null : input.image;
    const user = await this.userRepository.update(userId, patch);
    return this.buildAuthResponse(user);
  }

  /**
   * Sign a JWT for the given user.
   *
   * @param user - Domain user entity
   * @returns Signed JWT string
   */
  private generateToken(user: User): string {
    return sign({ id: user.id, email: user.email }, JWT_SECRET, { expiresIn: JWT_EXPIRY });
  }

  /**
   * Build the authenticated response DTO from a domain User entity.
   *
   * @param user - Domain user entity from the repository
   * @returns Response DTO with a freshly signed JWT attached
   */
  private buildAuthResponse(user: User): AuthenticatedUserResponse {
    return {
      email: user.email,
      token: this.generateToken(user),
      username: user.username,
      bio: user.bio,
      image: user.image,
    };
  }
}

import { formatError } from './formatError';

describe('formatError', () => {
  it('returns a resource-scoped error envelope', () => {
    const result = formatError('article', ['not found']);
    expect(result).toEqual({ errors: { article: ['not found'] } });
  });

  it('supports multiple messages for the same resource', () => {
    const result = formatError('user', ['is invalid', 'is required']);
    expect(result).toEqual({ errors: { user: ['is invalid', 'is required'] } });
  });

  it('uses the provided resource name as the key', () => {
    const result = formatError('profile', ['not found']);
    expect(Object.keys(result.errors)).toEqual(['profile']);
  });

  it('returns errors as an array even for a single message', () => {
    const result = formatError('comment', ['is missing']);
    expect(Array.isArray(result.errors.comment)).toBe(true);
  });
});

import { generateSlug } from './slugify';

describe('generateSlug', () => {
  it('lowercases the title', () => {
    const slug = generateSlug('Hello World');
    // prefix part is lowercase
    expect(slug.split('-').slice(0, -1).join('-')).toBe('hello-world');
  });

  it('replaces spaces with hyphens', () => {
    const slug = generateSlug('foo bar baz');
    expect(slug).toMatch(/^foo-bar-baz-/);
  });

  it('strips non-alphanumeric characters', () => {
    const slug = generateSlug('foo & bar!');
    expect(slug).toMatch(/^foo-bar-/);
  });

  it('appends an 8-character hex suffix for uniqueness', () => {
    const slug = generateSlug('my title');
    const suffix = slug.split('-').at(-1)!;
    expect(suffix).toHaveLength(8);
    expect(suffix).toMatch(/^[0-9a-f]{8}$/);
  });

  it('produces different slugs for the same title (random suffix)', () => {
    const slug1 = generateSlug('same title');
    const slug2 = generateSlug('same title');
    // Extremely unlikely to collide ΓÇö 1 in 2^32
    expect(slug1).not.toBe(slug2);
  });

  it('trims the slug base to 90 characters before the suffix', () => {
    const longTitle = 'a'.repeat(200);
    const slug = generateSlug(longTitle);
    // base-slug + '-' + 8-char suffix = at most 91 + 1 + 8 = 100 chars
    expect(slug.length).toBeLessThanOrEqual(100);
  });

  it('collapses multiple spaces and hyphens to a single hyphen', () => {
    const slug = generateSlug('foo   ---   bar');
    expect(slug).toMatch(/^foo-bar-/);
  });

  it('handles an all-symbol title gracefully', () => {
    const slug = generateSlug('!!!');
    // base is empty after stripping; suffix still appended
    expect(slug).toMatch(/^-?[0-9a-f]{8}$/);
  });
});
